def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/wildfire/input/noaa_wildfires_monthly_stats.csv'
    with open(path, 'r', encoding='utf-8', errors='replace') as f:
        lines = f.readlines()[:30]
    return pd.DataFrame({'line': [l.rstrip('\n') for l in lines]})

